package com.lmspilot.identity.domain; import jakarta.persistence.*; import java.time.Instant; import java.util.*; @Entity @Table(name="refresh_tokens",indexes=@Index(name="idx_refresh_hash",columnList="token_hash",unique=true)) public class RefreshTokenEntity { @Id public UUID id=UUID.randomUUID(); @Column(name="user_id",nullable=false) public UUID userId; @Column(name="token_hash",nullable=false,unique=true,length=64) public String tokenHash=""; @Column(nullable=false) public Instant issuedAt=Instant.now(); @Column(nullable=false) public Instant expiresAt; public Instant revokedAt; @Column(length=120) public String revokedReason; public Instant lastUsedAt; @Column(length=255) public String userAgent; @Column(length=80) public String ipAddress; public RefreshTokenEntity(){} }
